package dns

import (
	"context"
	"net/netip"
	"strings"
	"testing"
)

func TestParseResolvConf(t *testing.T) {
	content := `
# Generated by Kubernetes
search downloads.svc.cluster.local svc.cluster.local cluster.local
nameserver 10.96.0.10
nameserver 10.96.0.10
nameserver 2001:4860:4860::8888
options ndots:5
`
	servers, err := ParseResolvConf(strings.NewReader(content))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(servers) != 2 {
		t.Fatalf("got %d servers, want 2: %v", len(servers), servers)
	}
	if servers[0] != netip.MustParseAddr("10.96.0.10") {
		t.Errorf("servers[0] = %v", servers[0])
	}
	if servers[1] != netip.MustParseAddr("2001:4860:4860::8888") {
		t.Errorf("servers[1] = %v", servers[1])
	}
}

func TestResolveEndpointLiteralIP(t *testing.T) {
	r := &Resolver{}
	ip, err := r.ResolveEndpoint(context.Background(), "139.28.218.237", true)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if ip.String() != "139.28.218.237" {
		t.Errorf("got %s, want 139.28.218.237", ip)
	}
}

func TestPickAddr(t *testing.T) {
	ips := []netip.Addr{
		netip.MustParseAddr("2001:db8::1"),
		netip.MustParseAddr("198.51.100.10"),
	}
	got, err := pickAddr(ips, true)
	if err != nil || got.String() != "198.51.100.10" {
		t.Errorf("preferV4=true got (%v, %v)", got, err)
	}
	got6, err := pickAddr(ips, false)
	if err != nil || got6.String() != "2001:db8::1" {
		t.Errorf("preferV4=false got (%v, %v)", got6, err)
	}
}
